package com.bank.window.analysis;

import com.bank.window.model.MonthlyBalance;
import java.util.*;
import java.util.logging.Logger;

// Simulates AVG(..) OVER + LAG: per-account month-over-month growth check.
public class GrowthAnalyzer {
    private static final Logger log = Logger.getLogger(GrowthAnalyzer.class.getName());

    public List<String> accountsGrowingThreeMonths(List<MonthlyBalance> balances) {
        // PARTITION BY account_id ORDER BY month
        Map<String, List<MonthlyBalance>> byAcct = new LinkedHashMap<>();
        for (MonthlyBalance b : balances)
            byAcct.computeIfAbsent(b.getAccountId(), k -> new ArrayList<>()).add(b);

        List<String> growing = new ArrayList<>();
        for (Map.Entry<String, List<MonthlyBalance>> e : byAcct.entrySet()) {
            List<MonthlyBalance> list = e.getValue();
            list.sort(Comparator.comparingInt(MonthlyBalance::getMonth));
            int n = list.size();
            if (n >= 3) {
                // LAG(1) and LAG(2): avg_bal > prev1 > prev2
                boolean up = list.get(n - 1).getAvgBalance().compareTo(list.get(n - 2).getAvgBalance()) > 0
                          && list.get(n - 2).getAvgBalance().compareTo(list.get(n - 3).getAvgBalance()) > 0;
                if (up) {
                    growing.add(e.getKey());
                    log.info(() -> "GROWTH: " + e.getKey() + " rose 3 months in a row");
                }
            }
        }
        return growing;
    }
}
