package com.bank.window.analysis;

import com.bank.window.model.Txn;
import java.util.*;
import java.util.logging.Logger;

// Simulates ROW_NUMBER() OVER (PARTITION BY businessKey ORDER BY txnId).
public class DuplicateDetector {
    private static final Logger log = Logger.getLogger(DuplicateDetector.class.getName());

    public List<Txn> findDuplicates(List<Txn> txns) {
        Map<String, List<Txn>> partitions = new LinkedHashMap<>();
        for (Txn t : txns) partitions.computeIfAbsent(t.businessKey(), k -> new ArrayList<>()).add(t);

        List<Txn> duplicates = new ArrayList<>();
        for (List<Txn> part : partitions.values()) {
            part.sort(Comparator.comparing(Txn::getTxnId)); // ORDER BY txn_id
            for (int rn = 1; rn <= part.size(); rn++) {
                if (rn > 1) { // rn=1 is original; rn>1 duplicate
                    Txn dup = part.get(rn - 1);
                    duplicates.add(dup);
                    log.warning(() -> "DUPLICATE: " + dup.getTxnId() + " (rn>1) for key " + dup.businessKey());
                }
            }
        }
        return duplicates;
    }
}
