package com.bank.window;

import com.bank.window.analysis.*;
import com.bank.window.model.*;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class WindowDemo {
    private static final Logger log = Logger.getLogger(WindowDemo.class.getName());

    public static void main(String[] args) {
        log.info("=== Month-over-month growth (AVG OVER + LAG) ===");
        List<MonthlyBalance> balances = List.of(
            new MonthlyBalance("SAV2001", 7, new BigDecimal("900000")),
            new MonthlyBalance("SAV2001", 8, new BigDecimal("950000")),
            new MonthlyBalance("SAV2001", 9, new BigDecimal("1000000")), // rising → qualifies
            new MonthlyBalance("CUR3001", 7, new BigDecimal("300000")),
            new MonthlyBalance("CUR3001", 8, new BigDecimal("250000")),
            new MonthlyBalance("CUR3001", 9, new BigDecimal("280000"))   // not strictly rising
        );
        new GrowthAnalyzer().accountsGrowingThreeMonths(balances)
            .forEach(a -> log.info("Qualifying account: " + a));

        log.info("=== Duplicate detection (ROW_NUMBER OVER PARTITION BY) ===");
        List<Txn> txns = List.of(
            new Txn("T1", "SAV2001", new BigDecimal("1200"), "2024-10-29T10:00"),
            new Txn("T2", "SAV2001", new BigDecimal("1200"), "2024-10-29T10:00"), // duplicate of T1
            new Txn("T3", "CUR3001", new BigDecimal("5000"), "2024-10-29T11:00")
        );
        new DuplicateDetector().findDuplicates(txns)
            .forEach(d -> log.info("Flagged duplicate: " + d.getTxnId()));
    }
}
